/**
 * Scene Evaluated Frame Management.
 *
 * Provides a lightweight, unforgeable private mechanism (using WeakSet and internal metadata)
 * to distinguish ephemeral evaluation frames (generated by evaluateSceneAtTime or internal passes)
 * from canonical stored scene documents.
 *
 * Rules:
 * - A transient evaluated frame is marked internally upon creation.
 * - getRenderableSceneNodes checks if a frame is an authenticated transient frame to avoid double expansion.
 * - serialiseDocument strictly rejects baking transient evaluated frames into persistent storage.
 */

const EVALUATED_FRAMES = new WeakSet();
const CANONICAL_SOURCES = new WeakMap();

/**
 * Marks a document instance as an authenticated transient evaluated frame.
 * Optionally links it back to its original canonical document.
 *
 * @param {object} frameDoc - Evaluated frame document
 * @param {object|null} canonicalDoc - Source canonical document (if available)
 * @returns {object} The marked frameDoc
 */
export function markEvaluatedFrame(frameDoc, canonicalDoc = null) {
  if (frameDoc && typeof frameDoc === "object") {
    EVALUATED_FRAMES.add(frameDoc);
    if (canonicalDoc && typeof canonicalDoc === "object") {
      CANONICAL_SOURCES.set(frameDoc, canonicalDoc);
    }
  }
  return frameDoc;
}

/**
 * Checks whether a document object is an authenticated transient evaluated frame.
 * Unforgeable: public boolean properties like `doc.isEvaluatedFrame` are not trusted alone.
 *
 * @param {object} doc - Document object to test
 * @returns {boolean}
 */
export function isEvaluatedFrame(doc) {
  if (!doc || typeof doc !== "object") return false;
  return EVALUATED_FRAMES.has(doc);
}

/**
 * Retrieves the source canonical document for an evaluated frame, if available.
 *
 * @param {object} frameDoc
 * @returns {object|null}
 */
export function getCanonicalSource(frameDoc) {
  if (!frameDoc || typeof frameDoc !== "object") return null;
  return CANONICAL_SOURCES.get(frameDoc) || null;
}

/**
 * Asserts that a document is not an evaluated frame before baking/serializing.
 * Throws TypeError if the document is an evaluated transient frame.
 *
 * @param {object} doc
 */
export function assertNotEvaluatedFrame(doc) {
  if (
    isEvaluatedFrame(doc) ||
    doc?.isEvaluatedFrame === true ||
    (Array.isArray(doc?.nodes) &&
      doc.nodes.some((n) => Boolean(n?.arrayInstance)))
  ) {
    throw new TypeError(
      "Cannot serialize evaluated transient frame; transient evaluation must not be baked into persistent documents.",
    );
  }
}
